window.blogDetail = {"blogId":1578364545,"blogType":3,"pubTime":"2020-01-07 10:35","cate":"个人日记","cateHex":"b8f6c8cbc8d5bcc7","title":"异禀绝世神独立，才情兼得是佳人——“词宗” 李清照","commentNum":1,"effect1":8454657,"effect2":524294,"ar":0,"block":0,"inproc":false,"appeal":0,"abstract":"绣面一笑，却把春来闹；蹴罢秋千，拢袖和羞走，欲问女儿何处去，却回首，把那青梅嗅。多年后，抚今追昔，道当时正年幼。雨疏风骤，似是海棠依旧，多少心事难猜透。卖花旦上，一枝春花，把芳心泄漏。轻解罗裳，独上兰舟，将那情郎等候。花容月貌，惹得那梅花妒，菊花羞。何须人夸颜色好，自是文章第一流。无言独上西楼，两三杯淡酒，和着月光，化作《漱玉》照九州。曾经人杰，渡江东后，问鹿死谁手？国仇家恨，化作水悠悠，只恐双溪...","img":[{"url":"https://a1.qpic.cn/psc?/V115Q4qb1YRbBN/JBM4Sl1ltgGH1NeP*qvP3NiV9sFt.4X3VX4endvD7BSs1OKTq4tHMXfa8hKNMXFP6T.E8h1Sp9zv8M.hZELUH4jTPqLK*tFSSPMzdw6xkVU!/c&ek=1&kp=1&pt=0&bo=gAK9AYACvQERECc!&tl=1&su=0119202015&tm=1779170400&dis_t=1779172624&dis_k=371f9d47ab152e5ceaed4be058693103&sce=0-12-12&rf=0-2-8","custom_url":"images/166B1383.jpeg"},{"url":"https://a1.qpic.cn/psc?/V115Q4qb1YRbBN/JBM4Sl1ltgGH1NeP*qvP3PDc1JgDM3bR4Zijhgu1LzirrDSRO0y*XAV*h7TL5vUTzs06Lqm7m7z2yBMWsKWUXZSe.c2GuacjVxI1wGa9pWo!/c&ek=1&kp=1&pt=0&bo=gALzAYAC8wERECc!&tl=1&su=0105260335&tm=1779170400&dis_t=1779172624&dis_k=cf138abbed53c596511f50e3824b97b5&sce=0-12-12&rf=0-2-8","custom_url":"images/36211ADB.jpeg"}],"artype":1,"arUins":"","blogid":1578364545,"voteids":0,"pubtime":1578364545,"replynum":1,"category":"个人日记","effect":8454657,"exblogtype":3,"sus_flag":false,"friendrelation":[],"lp_type":0,"lp_id":81177,"lp_style":16843520,"lp_flag":0,"lp_topvalue":0,"orguin":619774944,"orgblogid":1578364545,"mention_uins":[],"attach":[],"comments":[{"id":1578364751,"postTime":1578364751,"effect":0,"replyNum":0,"content":"最近在策划着自己编一本《唐诗宋词的悲欢离合》，这是第五篇了，之前写过杜甫，李白，白居易，李煜，之后打算写一下苏轼 ","capacity":12054,"poster":{"id":"619774944","platform":1,"name":"秋天的怀念 ","emoji":[],"uin":"619774944"},"bmp":"08d015a10000c201","ismyreply":1,"replies":[]}],"html":"","custom_title":"异禀绝世神独立，才情兼得是佳人——“词宗” 李清照","custom_html":"","uniKey":"http://user.qzone.qq.com/619774944/blog/1578364545"}